"use client";
import { useActionState, useState } from "react";
import { send } from "@/app/contact/actions";
import { type ContactState, validate } from "@/lib/contact";

const initial: ContactState = { values: { name: "", email: "", message: "" }, errors: {} };

export default function ContactForm() {
  const [state, action] = useActionState(send, initial);
  const [local, setLocal] = useState<ContactState | null>(null);
  const view = local ?? state;
  const { values, errors } = view;

  return (
    <>
      {view.success && <p role="status">{view.success}</p>}
      <form
        action={action}
        noValidate
        onSubmit={(e) => {
          const fd = new FormData(e.currentTarget);
          const r = validate({
            name: String(fd.get("name")),
            email: String(fd.get("email")),
            message: String(fd.get("message")),
          });
          if (Object.keys(r.errors).length) {
            e.preventDefault();
            setLocal({ ...r, values: {
              name: String(fd.get("name")),
              email: String(fd.get("email")),
              message: String(fd.get("message")),
            } });
          } else {
            setLocal(null);
          }
        }}
      >
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" defaultValue={values.name} key={`n${values.name}`} />
          {errors.name && <span>{errors.name}</span>}
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" defaultValue={values.email} key={`e${values.email}`} />
          {errors.email && <span>{errors.email}</span>}
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" defaultValue={values.message} key={`m${values.message}`} />
          {errors.message && <span>{errors.message}</span>}
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
