import fs from "node:fs";
import path from "node:path";
import { NextRequest, NextResponse } from "next/server";

export function proxy(request: NextRequest) {
  const slug = decodeURIComponent(request.nextUrl.pathname.split("/")[2] ?? "");
  const file = path.join(process.cwd(), "content", "books", `${slug}.md`);
  if (!/^[\w-]+$/.test(slug) || !fs.existsSync(file)) {
    return NextResponse.rewrite(new URL("/not-found-page", request.url));
  }
}

export const config = { matcher: "/books/:slug" };
